insert into public.goals (id, name, description, badge, position) values
  ('learn-ai', 'Learn AI', 'Understand AI basics, prompts, and practical workflows that improve everyday work.', 'AI', 0),
  ('build-website', 'Build a website', 'Learn the basics of design and publishing so you can launch a simple online presence.', 'Web', 1),
  ('automate-work', 'Automate my work', 'Use no-code workflows to handle repetitive tasks and save time in your day.', 'Workflow', 2),
  ('learn-coding', 'Learn coding', 'Start with beginner-friendly coding tools and tiny real-world project ideas.', 'Coding', 3),
  ('learn-ml', 'Learn machine learning', 'Understand the foundations of ML, data patterns, and practical experiments.', 'ML', 4),
  ('design-cad', 'Use CAD and design tools', 'Explore beginner-friendly design, 3D, and product design tools for creative work.', 'Design', 5),
  ('build-app', 'Build an app', 'Turn a product idea into a real first step with a simple app-building roadmap.', 'App', 6),
  ('no-code', 'Use no-code tools', 'Build faster with tools that help you automate, organize, and launch without code.', 'No-code', 7),
  ('ai-productivity', 'Improve AI productivity', 'Learn how AI can help with research, writing, planning, and smarter daily tasks.', 'Productivity', 8),
  ('create-content', 'Create content', 'Make posts, images, voice-overs and short videos with AI helpers, then polish them in your own voice.', 'Content', 9),
  ('analyze-data', 'Analyze data', 'Turn measurements into clear graphs, numbers and decisions with analysis software and AI help.', 'Data', 10),
  ('visualize-data', 'Visualize data', 'Choose clear charts and explain what data shows with honest, accessible visualizations.', 'Data', 11),
  ('research-ai', 'Research with AI', 'Use AI to organise research while finding, checking and citing real sources.', 'Research', 12),
  ('ai-education', 'AI for teachers and students', 'Use AI to support lesson planning, tutoring and practice while protecting privacy and academic integrity.', 'Education', 13),
  ('ai-small-business', 'AI for small business', 'Research customer needs and draft useful business content with AI, then verify it before publishing.', 'Business', 14),
  ('ai-career', 'Build career skills with AI', 'Prepare truthful applications, practise interviews and organise your job search with AI support.', 'Career', 15),
  ('start-ai-business', 'Start an AI service business', 'Validate one customer problem, test a safe automation demo and prepare an evidence-based pilot offer.', 'Business', 16),
  ('offer-content-services', 'Offer AI content services', 'Prepare a checked content package, manage revisions and scope an honest client service.', 'Business', 17),
  ('offer-cad-services', 'Offer AI + CAD concept services', 'Prepare non-functional concept views with checked dimensions, licensing boundaries and review evidence.', 'Design', 18),
  ('validate-micro-saas', 'Validate a micro-SaaS idea', 'Investigate a recurring problem, test a local prototype and review demand before building subscriptions.', 'Business', 19),
  ('offer-education-services', 'Offer AI education services', 'Design an original adult workshop with a checked answer key, accessible materials and a bounded offer.', 'Education', 20)
