  ('offer-cad-services', 'AI + CAD Concept Services', 'Prepare a non-functional display-card concept with consistent dimensions, versioned views and clear exclusions.', array['Define concept-only boundaries', 'Sketch and check dimensions', 'Model or document a paper alternative', 'Review revisions and hand over concept evidence']::text[]),
  ('validate-micro-saas', 'Micro-SaaS Validation', 'Validate a narrow problem with a local-only formatter prototype, boundary tests and honest user evidence.', array['Gather problem evidence', 'Specify and prototype a tiny service', 'Test boundaries and cost assumptions', 'Observe use and decide before launch']::text[]),
  ('offer-education-services', 'AI Education Services', 'Prepare an original adult workshop with source-checked materials, a practice rubric and accessible delivery.', array['Define an adult learning objective', 'Create original materials and a checked key', 'Rehearse and review accessibility', 'Scope the workshop and improve from evidence']::text[]),
  ('start-ai-business', 'Your AI Automation Service Pilot', 'Start with evidence of a customer problem, not an income promise. Build a fictional administrative demo before agreeing to any live work.', array['Validate one customer problem', 'Define a safe, bounded pilot', 'Build and test a fictional enquiry demo', 'Calculate costs and prepare an honest offer', 'Plan handover and review the evidence']::text[]),
  ('learn-ai', 'AI for Beginners', 'Start with AI basics, prompt writing, and simple real-world workflows before moving into deeper tool usage.', array['Understand AI basics', 'Learn prompt writing', 'Use AI in daily tasks', 'Build a small practical project']::text[]),
  ('build-website', 'Website Builder Path', 'Learn the essential steps for designing, creating, and publishing a simple website without feeling lost.', array['Learn structure and design', 'Create a simple layout', 'Publish your first page', 'Refine and share']::text[]),
  ('automate-work', 'Automation Starter', 'Use beginner-friendly tools to reduce repetitive tasks and improve the way you work.', array['Identify a repetitive task', 'Choose a workflow tool', 'Connect two or three tools', 'Test and adjust']::text[]),
  ('learn-coding', 'Coding Foundations', 'Learn the basics of coding and use small projects to build confidence before deeper learning.', array['Set up your workspace', 'Learn basic logic', 'Build a simple script', 'Use AI to explain and review your code', 'Practice with mini projects']::text[]),
  ('learn-ml', 'Machine Learning Foundations', 'Understand the big ideas behind ML, data patterns, and beginner-friendly experiments.', array['Learn key ML concepts', 'Work with data', 'Try a notebook', 'Practice and review']::text[]),
  ('design-cad', 'Design and CAD Path', 'Use design thinking and simple CAD tools to build creative ideas and prototypes with confidence.', array['Learn design basics', 'Explore a tool', 'Create simple concepts', 'Refine and share']::text[]),
  ('build-app', 'App Building Path', 'Start with simple app ideas, product thinking, and the tools that help you build a first version.', array['Define the idea and tiny scope', 'Sketch the user flow', 'Build a prototype with an AI coding assistant', 'Test with real people', 'Publish and improve']::text[]),
  ('no-code', 'No-Code Starter', 'Use easy tools to build workflows and small systems without needing to write code.', array['Choose a simple problem', 'Map the flow', 'Build the workflow', 'Review and improve']::text[]),
  ('ai-productivity', 'AI Productivity Path', 'Learn how AI can support writing, planning, research, and daily work in a practical way.', array['Identify daily repetitive tasks', 'Create reusable prompts', 'Apply AI to real work', 'Review and improve results']::text[]),
  ('create-content', 'Content Creation Path', 'Plan an idea, draft it with AI, add visuals or voice, then polish it in your own voice before you share.', array['Pick one audience and message', 'Draft with an AI assistant', 'Add images, voice or video', 'Edit, check facts and publish']::text[]),
  ('analyze-data', 'Data Analysis Path', 'Learn to import, plot, measure and report on measurement data such as pump logs and scanner maps. Use Origin for graphs, or automate the analysis with Python scripts and AI assistants.', array['Write your analysis question', 'Import, label and plot data', 'Measure stability, integrate and fit', 'Map scans, then template and report']::text[]),
  ('visualize-data', 'Data Visualization Path', 'Use clear charts to answer questions about data. Start with clean tables, choose a chart, create it in Python or Colab and explain its limits.', array['Choose a question and chart', 'Prepare and label data', 'Create and review visualizations', 'Explain the evidence and limitations']::text[]),
  ('research-ai', 'Research Prompting Path', 'Use AI to narrow research questions, organize evidence and draft synthesis, while verifying original sources and every citation yourself.', array['Focus a research question', 'Find real sources', 'Compare evidence and limitations', 'Verify and cite the final brief']::text[]),
  ('ai-education', 'AI for Teachers and Students Path', 'Use AI for lesson planning, tutoring and practice without sharing personal student data or handing over human judgement and learning.', array['Set privacy and course rules', 'Plan a lesson or study with a tutor', 'Create and review practice', 'Reflect on and disclose AI use']::text[]),
  ('ai-small-business', 'Small Business Content Path', 'Start with real customer evidence, draft useful content and check every claim before sharing.', array['Define an offer and research customer needs', 'Draft a truthful product description', 'Create a checked FAQ', 'Plan, review and measure a small campaign']::text[]),
  ('ai-career', 'Career Skills Path', 'Use real experience to prepare applications and interview practice, then plan a manageable skill-building project.', array['Match a role to real evidence', 'Tailor a resume and cover letter', 'Practise interview answers', 'Track applications and choose a learning goal']::text[])
